          } catch (e) {
            reject(e)
          }
        }
      ),
    [callback]
  )
  const invoke = useSetAtom(anAtom, scope)
  return useCallback(
    (arg: Arg) =>
      new Promise<Result>((resolve, reject) => {
        invoke([arg, resolve, reject])
      }),
